import { db } from "./db";

export type OrderStatus = "paid" | "cancelled";

export interface Order {
  id: string;
  status: OrderStatus;
  totalCents: number;
  createdAt: string;
}

export async function cancelOrder(orderId: string): Promise<void> {
  await db.query("UPDATE orders SET status = 'cancelled' WHERE id = $1", [orderId]);
}

